    "CLOSED"
  ],
  "transitions": [
    {
      "from": "ESTABLISHED",
      "event": "(Close)",
      "action": "construct and place on outgoing segment queue, enters the FIN-WAIT-1 state",
      "to": "FIN-WAIT-1"
    },
    {
      "from": "ESTABLISHED",
      "event": "FIN",
      "action": "tell the user that the connection is closing, send a FIN",
      "to": "CLOSE-WAIT"
    },
    {
      "from": "FIN-WAIT-1",
      "event": "FIN",
      "action": "ACK this FIN",
      "to": "FIN-WAIT-2"
    },
    {
      "from": "FIN-WAIT-1",
      "event": "FIN",
      "action": "exchange FIN segments",
      "to": "CLOSING"
    },
    {
      "from": "CLOSE-WAIT",
      "event": "(Close)",
      "action": "send a FIN to the other TCP peer after sending any remaining data",
      "to": "LAST-ACK"
    },
    {
      "from": "CLOSING",
      "event": "ACK",
      "action": "ACK the FIN it has received",
      "to": "TIME-WAIT"
    },
    {
      "from": "LAST-ACK",
      "event": "ACK",
      "action": "deletes the connection",
      "to": "CLOSED"
    },
    {
      "from": "TIME-WAIT",
      "event": "2 MSL",
      "action": "delete the connection",
      "to": "CLOSED"
    }
  ]
}

{
  "states": [
    "CLOSED STATE",
    "LISTEN STATE",
    "SYN-SENT STATE",
    "SYN-RECEIVED STATE",
    "ESTABLISHED STATE",
    "FIN-WAIT-1 STATE",
    "FIN-WAIT-2 STATE",
    "CLOSE-WAIT STATE",
    "CLOSING STATE",
    "LAST-ACK STATE",
    "TIME-WAIT STATE"
  ],
  "transitions": [
    {
      "from": "CLOSED STATE",
      "event": "OPEN",
      "action": "Create a new transmission control block (TCB) to hold connection state information. Fill in local socket identifier, remote socket, Diffserv field, security/compartment, and user timeout information. Note that some parts of the remote socket may be unspecified in a passive OPEN and are to be filled in by the parameters of the incoming SYN segment. Verify the security and Diffserv value requested are allowed for this user, if not, return \"error: Diffserv value not allowed\" or \"error: security/ compartment not allowed\". If passive, enter the LISTEN state and return.",
      "to": "LISTEN STATE"
    },
    {
      "from": "CLOSED STATE",
      "event": "OPEN",
      "action": "If active and the remote socket is specified, issue a SYN segment. An initial send sequence number (ISS) is selected. A SYN segment of the form <SEQ=ISS><CTL=SYN> is sent. Set SND.UNA to ISS, SND.NXT to ISS+1, enter SYN-SENT state, and return.",
      "to": "SYN-SENT STATE"
    },
    {
      "from": "LISTEN STATE",
      "event": "OPEN",
      "action": "If the OPEN call is active and the remote socket is specified, then change the connection from passive to active, select an ISS. Send a SYN segment, set SND.UNA to ISS, SND.NXT to ISS+1. Enter SYN-SENT state.",
      "to": "SYN-SENT STATE"
    },
    {
      "from": "LISTEN STATE",
      "event": "SEGMENT ARRIVES",
      "action": "If the SYN bit is set, check the security. If the security/ compartment on the incoming segment does not exactly match the security/compartment in the TCB, then send a reset and return. Set RCV.NXT to SEG.SEQ+1, IRS is set to SEG.SEQ, and any other control or text should be queued for processing later. ISS should be selected and a SYN segment sent of the form: <SEQ=ISS><ACK=RCV.NXT><CTL=SYN,ACK>. SND.NXT is set to ISS+1 and SND.UNA to ISS. The connection state should be changed to SYN-RECEIVED.",
      "to": "SYN-RECEIVED STATE"
    },
    {
      "from": "LISTEN STATE",
      "event": "SEGMENT ARRIVES",
      "action": "An acceptable reset segment should be formed for any arriving ACK-bearing segment. The RST should be formatted as follows: <SEQ=SEG.ACK><CTL=RST>. Return.",
      "to": "LISTEN STATE"
    },
    {
      "from": "SYN-SENT STATE",
      "event": "SEGMENT ARRIVES",
      "action": "If SND.UNA > ISS (our SYN has been ACKed), change the connection state to ESTABLISHED, form an ACK segment <SEQ=SND.NXT><ACK=RCV.NXT><CTL=ACK> and send it. Data or controls that were queued for transmission MAY be included.",
      "to": "ESTABLISHED STATE"
    },
    {
      "from": "SYN-SENT STATE",
      "event": "SEGMENT ARRIVES",
      "action": "If the SYN bit is on and the security/compartment is acceptable, then RCV.NXT is set to SEG.SEQ+1, IRS is set to SEG.SEQ. SND.UNA should be advanced to equal SEG.ACK (if there is an ACK), and any segments on the retransmission queue that are thereby acknowledged should be removed. Otherwise, enter SYN-RECEIVED, form a SYN,ACK segment <SEQ=ISS><ACK=RCV.NXT><CTL=SYN,ACK> and send it.",
      "to": "SYN-RECEIVED STATE"
    },
    {
      "from": "SYN-SENT STATE",
      "event": "CLOSE",
      "action": "Delete the TCB and return \"error: closing\" responses to any queued SENDs, or RECEIVEs.",
      "to": "CLOSED STATE"
    },
    {
      "from": "SYN-SENT STATE",
      "event": "ABORT",
      "action": "All queued SENDs and RECEIVEs should be given \"connection reset\" notification. Delete the TCB, enter CLOSED state, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "SYN-SENT STATE",
      "event": "SEGMENT ARRIVES",
      "action": "If the RST bit is set... If the ACK was acceptable, then signal to the user \"error: connection reset\", drop the segment, enter CLOSED state, delete TCB, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "SYN-RECEIVED STATE",
      "event": "CLOSE",
      "action": "If no SENDs have been issued and there is no pending data to send, then form a FIN segment and send it, and enter FIN-WAIT-1 state.",
      "to": "FIN-WAIT-1 STATE"
    },
    {
      "from": "ESTABLISHED STATE",
      "event": "CLOSE",
      "action": "Queue this until all preceding SENDs have been segmentized, then form a FIN segment and send it. In any case, enter FIN-WAIT-1 state.",
      "to": "FIN-WAIT-1 STATE"
    },
    {
      "from": "ESTABLISHED STATE",
      "event": "SEND",
      "action": "Segmentize the buffer and send it with a piggybacked acknowledgment (acknowledgment value = RCV.NXT). If there is insufficient space to remember this buffer, simply return \"error: insufficient resources\".",
      "to": "ESTABLISHED STATE"
    },
    {
      "from": "ESTABLISHED STATE",
      "event": "RECEIVE",
      "action": "Reassemble queued incoming segments into receive buffer and return to user. Mark \"push seen\" (PUSH) if this is the case.",
      "to": "ESTABLISHED STATE"
    },
    {
      "from": "CLOSE-WAIT STATE",
      "event": "CLOSE",
      "action": "Queue this request until all preceding SENDs have been segmentized; then send a FIN segment, enter LAST-ACK state.",
      "to": "LAST-ACK STATE"
    },
    {
      "from": "LISTEN STATE",
      "event": "CLOSE",
      "action": "Any outstanding RECEIVEs are returned with \"error: closing\" responses. Delete TCB, enter CLOSED state, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "SYN-RECEIVED STATE",
      "event": "ABORT",
      "action": "All queued SENDs and RECEIVEs should be given \"connection reset\" notification. Delete the TCB, enter CLOSED state, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "ESTABLISHED STATE",
      "event": "ABORT",
      "action": "Send a reset segment: <SEQ=SND.NXT><CTL=RST>. All queued SENDs and RECEIVEs should be given \"connection reset\" notification; all segments queued for transmission (except for the RST formed above) or retransmission should be flushed. Delete the TCB, enter CLOSED state, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "FIN-WAIT-1 STATE",
      "event": "ABORT",
      "action": "Send a reset segment: <SEQ=SND.NXT><CTL=RST>. All queued SENDs and RECEIVEs should be given \"connection reset\" notification; all segments queued for transmission (except for the RST formed above) or retransmission should be flushed. Delete the TCB, enter CLOSED state, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "FIN-WAIT-2 STATE",
      "event": "ABORT",
      "action": "Send a reset segment: <SEQ=SND.NXT><CTL=RST>. All queued SENDs and RECEIVEs should be given \"connection reset\" notification; all segments queued for transmission (except for the RST formed above) or retransmission should be flushed. Delete the TCB, enter CLOSED state, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "CLOSE-WAIT STATE",
      "event": "ABORT",
      "action": "Send a reset segment: <SEQ=SND.NXT><CTL=RST>. All queued SENDs and RECEIVEs should be given \"connection reset\" notification; all segments queued for transmission (except for the RST formed above) or retransmission should be flushed. Delete the TCB, enter CLOSED state, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "CLOSING STATE",
      "event": "ABORT",
      "action": "Respond with \"ok\" and delete the TCB, enter CLOSED state, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "LAST-ACK STATE",
      "event": "ABORT",
      "action": "Respond with \"ok\" and delete the TCB, enter CLOSED state, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "TIME-WAIT STATE",
      "event": "ABORT",
      "action": "Respond with \"ok\" and delete the TCB, enter CLOSED state, and return.",
      "to": "CLOSED STATE"
    },
    {
      "from": "CLOSED STATE",
      "event": "SEGMENT ARRIVES",
      "action": "An incoming segment not containing a RST causes a RST to be sent in response. The acknowledgment and sequence field values are selected to make the reset sequence acceptable to the TCP endpoint that sent the offending segment.",
      "to": "CLOSED STATE"
    },
    {
      "from": "LISTEN STATE",
      "event": "SEGMENT ARRIVES",
      "action": "An incoming RST should be ignored. Return.",
      "to": "LISTEN STATE"
    }
  ]
}

